    'pv_L10_007': 'ධනය, දේපල (නියුටර්)',
    'pv_L10_008': 'ඛේදජනක තත්ත්වය, නරක ගමනාන්තය (fem.)',
    'pv_L10_009': 'සැබවින්ම, ඇත්ත වශයෙන්ම (ඉවත් කළ නොහැකි)',
    'pv_L10_010': 'කැමති, (ඉවත් කළ නොහැකි)',
    'pv_L10_011': 'මව (fem. -ī)',
    'pv_L10_012': 'රැජින, රාජකීය භාර්යාව (fem. -ī)',
    'pv_L10_013': 'බුද්ධිමත් පුද්ගලයා (masc. -ī)',
    'pv_L10_014': 'නපුරු, පාපය (නපුරු)',
    'pv_L10_015': 'නපුර කරන්නා (masc. -ī)',
    'pv_L10_016': 'කුසලය, යහපත් ක්‍රියාව (නපුංසක)',
    'pv_L10_017': 'පින් කරන්නා (masc. -ī)',
    'pv_L10_018': 'ප්‍රමුඛ, ප්‍රධාන, හොඳම (විශේෂණ පදය)',
    'pv_L10_019': 'ප්‍රීතිමත් තත්වයක්, හොඳ ගමනාන්තයක් (fem.)',
    'pv_L10_020': 'එළු එළු (fem., aja වෙතින්)',
    'pv_L10_021': 'mare (fem., assa වෙතින්)',
    'pv_L10_022': 'ස්ත්‍රී ගිහි අනුගාමිකයා (fem., upāsaka වෙතින්)',
    'pv_L10_023': 'සේවිකාව, සේවිකාව (ස්ත්‍රිය, dāsa වෙතින්)',
    'pv_L10_024': 'දේවතාවිය, රැජින (fem., deva වෙතින්)',
    'pv_L10_025': 'රැජින (fem., rāja වෙතින්)',
    'pv_L10_026': 'ගැහැණු අලි (ෆෙම්., හත්ති සිට)',
    'pv_L10_027': 'ප්‍රඥාවේ කාන්තාව (fem., medhāvī වෙතින්)',
    'pv_L10_028': 'කන්‍යා සොහොයුරිය (භික්ෂුවගෙන්)',
    'pv_L10_029': 'නැන්දා (මාතෘ) (ස්ත්‍රී., mātula සිට අක්‍රමවත්)',
    'pv_L10_030': 'ගෘහපතියාගේ බිරිඳ (ගැහැණු., ගහපති සිට අක්‍රමවත්)',
    'pv_L10_031': 'සහෝදරිය (එකම දෙමාපිය) (ෆෙම්.)',
    'pv_L10_032': 'අතේ මල් සහිත එකක් (fem.)',
    'pv_L10_033': 'ආරක්ෂා කරයි, ආරක්ෂකයින්',
    'pv_L10_034': 'කරයි, කරයි; අතීතය: akaṃsu / katvā (කළ පසු)',
    'pv_L10_035': 'දෙයි, ප්‍රදානය කරයි; අතීතය: adaṃsu (ඔවුන් දුන්නා)',
    'pv_L10_036': 'ගියා (ගච්චති අතීතය)',
    'pv_L10_037': 'එනවා, ළඟා වෙනවා; අනාගතය: pāpuṇissati; අතීතය: pāpuṇi',
    'pv_L10_038': 'සහභාගී වෙනවා, බලාගන්නවා, සේවය කරනවා',
    'pv_L10_039': 'යි, වෙයි; අතීතය: āsi (pl. homa = අපි/වෙනව)',
    'pv_L10_040': 'වැටීම, වැටීම්, බැසීම්; අතීතය: pati (වැටුණා)',
    'pv_L10_041': 'දකියි; අතීතය: addasa / disvā (දැකීමෙන් පසු)',
    'pv_L10_042': 'ලකුණු; අතීතය: dhāviṃsu (ඔවුන් දිව ගියා)',
    'pv_L10_043': 'පලා යයි, පලා යයි; අතීතය: palāyiṃsu (ඔවුන් පලා ගියා)',
    'pv_L10_044': 'අධ්‍යයනය, මාස්ටර්',
    'pv_L10_045': 'ඉහළට නගිනවා, සවි කරනවා',
    'pv_L10_046': 'අලියා (masc. -i/-ī)',
    'pv_L10_047': 'අලි (no. pl. hatthī / පිරිමි අලි)',
    'pv_L10_048': 'මගේ (සන්තක සර්වනාමය)',
    'pv_L10_049': 'ඔහුගේ/ඇය (සර්වනාමය)',
    'pv_L10_050': 'දාන, ආහාර (දානයෙන් ලබා ගන්නා ලද) (මාස්ක්.)',
    'pv_L10_051': 'ඊයේ (කාල ඇඩ්වර්බ්)',
    'pv_L12_001': 'I (No. sg.)',
    'pv_L12_002': 'අපි (නම්. pl.)',
    'pv_L12_003': 'මම (acc. sg.)',
    'pv_L12_004': 'මා විසින්/මා හරහා, මා සමඟ (inst./abl. sg.)',
    'pv_L12_005': 'මගේ, මට (gen./dat. sg.)',
    'pv_L12_006': 'මා තුළ, මා මත (loc. sg.)',
    'pv_L12_007': 'I / my / for me (enclitic, වාක්‍යයේ ආරම්භයේදී නොවේ)',
    'pv_L12_008': 'අපි / අපගේ (වැකිය ආරම්භයේදී නොවේ)',
    'pv_L12_009': 'ඔබ (නාම. sg.)',
    'pv_L12_010': 'ඔබ (pl.) (nom./acc. pl.)',
    'pv_L12_011': 'ඔබ (acc. sg.)',
    'pv_L12_012': 'ඔබ විසින්/ඔබ හරහා (inst./abl. sg.)',
    'pv_L12_013': 'ඔබේ, ඔබ වෙනුවෙන් (gen./dat. sg.)',
    'pv_L12_014': 'ඔබ තුළ, ඔබ මත (loc. sg.)',
    'pv_L12_015': 'ඔබ / ඔබේ / ඔබ වෙනුවෙන් (එන්ක්ලිටික්, වාක්‍යයේ ආරම්භයේදී නොවේ)',
    'pv_L12_016': 'ඔබ (pl.) / ඔබේ (එන්ක්ලිටික්, වාක්‍යයේ ආරම්භයේ නොවේ)',
    'pv_L12_017': 'බොරුකාරයා, බොරු ස්පීකර් (මැස්ක්.)',
    'pv_L12_018': 'වාර්තා, තොරතුරු, නිවේදනය',
    'pv_L12_019': 'දුෂ්ට පුද්ගලයා, නරක පුද්ගලයා; දුෂ්ට (masc./adjective)',
    'pv_L12_020': 'සේවය කරයි, ආශ්‍රය කරයි, සමීපයි',
    'pv_L12_021': 'කියනවා, සජ්ඣායනා කරනවා, දේශනා කරනවා (උදා. bhaṇeyya = කිව යුතුයි)',
    'pv_L12_022': 'දීම, දානය, ත්‍යාගශීලි බව (නපුරුකම)',
    'pv_L12_023': 'එසේ, (ඉවත් කළ නොහැකි)',
    'pv_L12_024': 'ජය කරයි, ජය ගනී',
    'pv_L12_025': 'කාලකන්නි, මසුරු පුද්ගලයා (masc.)',
    'pv_L12_026': 'කෝපය, ක්‍රෝධය (masc.)',
    'pv_L12_027': 'ඉක්මනින්, එකවර (විශේෂ පදය)',
    'pv_L12_028': 'ප්‍රඥාවන්ත, උගත් පුද්ගලයා (masc.)',
    'pv_L12_029': 'නරක, නපුරු, පව්කාර (විශේෂණ පදය)',
    'pv_L12_030': 'හොඳ පුද්ගලයා; යහපත්, විශිෂ්ට වූ; හොඳින් කළා! (masc./adverb/exclamation)',
    'pv_L12_031': 'උත්සාහ කරයි, උත්සාහ කරයි, උත්සාහ කරයි',
    'pv_L12_032': 'සංකීර්ණය, වර්ණය, අලංකාරය, ප්‍රශංසාව, පන්තිය (masc.)',
    'pv_L12_033': 'සත්‍යය, සත්‍යය (උදාසීන)',
    'pv_L12_034': 'විට (සාපේක්ෂ සර්වනාමය, නොපැහැදිලි)',
    'pv_L12_035': 'එසේ නම්, එම අවස්ථාවේදී (ඉවත් කළ නොහැකි)',
    'pv_L12_036': 'නම් (කොන්දේසි සහිත සංයෝජනය)',
    'pv_L12_037': 'තාක්, (සන්ධිය) දක්වා',
    'pv_L12_038': 'ඉන්පසු, එම කාලය දක්වා (yāva සහසම්බන්ධය)',
    'pv_L12_039': 'දක්ෂ ලෙස, ප්‍රවේශමෙන් (ක්‍රියා පදය)',
    'pv_L12_040': 'කෝපයෙන් තොරව, කෝපයෙන් නිදහස් (masc.)',
    'pv_L12_041': 'කෝප වේ, කෝපයට පත් වේ (උදා: නා කුජ්ජෙය්‍ය = කෝප නොවිය යුතුය)',
    'pv_L12_042': 'ජය කරයි, යටපත් කරයි, ජය ගනී',
    'pv_L12_043': 'ස්වාමියා, නායකයා, ස්වාමිපුරුෂයා (masc.)',
    'pv_L12_044': 'පූජ්‍ය සර් (භික්ෂුව/තපස් වහන්සේ සඳහා ලිපිනය)',
    'pv_L12_045': 'ප්‍රශ්නය (masc.)',
    'pv_L12_046': 'අසයි (pucchituṃ = ඇසීමට)',
    'pv_L12_047': 'සෑම විටම, නිරන්තරයෙන් (ක්‍රියාවිශේෂාංග)',
    'pv_L12_048': 'යවයි, යැවීම්',
    'pv_L12_049': 'අවබෝධය, අවබෝධය, අවබෝධය',
    'pv_L12_050': 'මිතුරන් (masc./fem.)',
    'pv_L12_051': 'ගෙන එනවා, රැගෙන යයි (āhareyyāsi = ඔබ ගෙන ආ යුතුයි)',
    'pv_L16_001': 'එකක් (1) — 3 ස්ත්‍රී පුරුෂ: eko / ekā / ekaṃ',
    'pv_L16_002': 'දෙක (2) — බහු වචන පමණි: dve / duve',
    'pv_L16_003': 'තුන (3) — tayo / tīni / tisso',
    'pv_L16_004': 'හතර (4) — cattāro/caturo / cattāri / catasso',
