    'pv_L16_048': '35/35 වසර (pañca-tiṃsatime vasse)',
    'pv_L16_049': 'දිනය (masc./neuter)',
    'pv_L16_050': 'මෙතනින්, සිට, පෙර (නොමැකෙන)',
    'pv_L16_051': 'මාසය (masc./neuter)',
    'pv_L16_052': 'නමුත්, එපමනක් නොව, (ඉවත් කළ නොහැකි)',
    'pv_L16_053': 'පරිච්ඡේදය, කොටස, මායිම, සීමාව (masc.)',
    'pv_L16_054': 'සරණාගමනය, රැකවරණය ලබා ගැනීම (නියුටර්)',
    'pv_L16_055': 'සුචරිතය, සදාචාරය, ශික්ෂා පදය (නපුරු, සාමාන්‍යයෙන් බහු වචන sīlāni)',
