    'pv_L16_067': 'ගෘහ හිමියා; බහු ආකාරය gahapatī (masc. -i)',
    'pv_L16_068': 'ගුණවත්, ගුණයෙන් යුක්ත (විශේෂණ පදය)',
    'pv_L16_069': 'උපෝසථ (සමාදන් වීමේ දිනය)',
    'pv_L16_070': 'භික්ෂුව (masc. -u)',
    'pv_L16_071': 'පුහුණු රීතිය, ශික්ෂා පදය (නපුංසක)',
    'pv_L16_072': 'ධනවත් ගෘහපති, කෝටිපති (masc.)',
    'pv_L16_073': 'හතළිස් පහ koṭi / මිලියන 450 (සංයුක්ත සංඛ්‍යා)',
    'pv_L16_074': 'ආයුෂ, ආයු කාලය (masc./neuter)',
    'pv_L16_075': 'සම්පූර්ණ ස්වයං ප්‍රබුද්ධ තැනැත්තා (මස්; පූර්ණ බුද්ධත්වයට පත් බුදු කෙනෙක්)',
    'pv_L16_076': 'ඇස (masc., බහු වචන cakkhūni)',
    'pv_L16_077': 'මුහුණ, මුඛය (වංකය)',
    'pv_L16_078': 'අඹ (masc./neuter)',
    'pv_L16_079': 'ත්‍රිසරණ (වංක: බුද්ධ, ධම්ම, Saṅgha)',
    'pv_L16_080': 'ප්‍රතිපත්ති පහ (උදාසීන, බහු වචන pañca sīlāni)',
    'pv_L16_081': 'අසනීප පුද්ගලයා (masc./neuter)',
    'pv_L16_082': 'ආයුකාලය (ඉහත බලන්න)',
    'pv_L16_083': 'ධර්මය (masc., බහු වචන Dhammā / Dhammāni ස්ත්‍රී පුරුෂ භාවය අනුව)',
    'pv_L20_001': 'තරුණයා (taruṇa+purisa) — KAMMADHĀRAYA',
    'pv_L20_002': 'තරුණ දැරිය, තරුණ තරුණිය — KAMMADHĀRAYA (fem.)',
    'pv_L20_003': 'නොඉදුණු පලතුරු, තරුණ පලතුරු — KAMMADHĀRAYA (neut.)',
    'pv_L20_004': 'සඳ මුහුණ (සඳ වැනි මුහුණ) — KAMMADHĀRAYA (masc.)',
    'pv_L20_005': 'ගුණයේ ධනය (ගුණය ධනය ලෙස) — KAMMADHĀRAYA (neut.)',
    'pv_L20_006': 'යහපත් මිනිසා, උතුම් පුද්ගලයා (සු+ජන) — KAMMADHĀRAYA (masc.)',
    'pv_L20_007': 'අහිතකර (a+kusala) — KAMMADHĀRAYA (neut.)',
    'pv_L20_008': 'අශ්වයෙක් නොවේ → කොටළුවා (an+assa) — KAMMADHĀRAYA (masc.)',
    'pv_L20_009': 'මිනිසා නොවේ → ආත්මය, අවතාරය (a+manussa) — KAMMADHĀRAYA (masc.)',
    'pv_L20_010': 'ප්‍රඥාවන්ත සුමේධා (අනුකූල) — KAMMADHĀRAYA (masc.)',
    'pv_L20_011': 'ලෝක තුන (එකතු කිරීම) — DIGU (neut.)',
    'pv_L20_012': 'සතර ආර්ය සත්‍ය (සත්‍ය හතර, එකතුව) — DIGU (neut.)',
    'pv_L20_013': 'දිශා හතර (එකතු කිරීම) — DIGU (neut.)',
    'pv_L20_014': 'සතියකට (දින හතක්) — DIGU (neut.)',
    'pv_L20_015': 'එකම දරුවා (එක පුතෙක් සිටී) — DIGU / KAMMADHĀRAYA (masc.)',
    'pv_L20_016': 'ගමට ගොස් ඇත (acc.) — TAPPURISA (masc.)',
    'pv_L20_017': 'බුදුන් විසින් දේශනා කරන ලදී (උපදේශනය) — TAPPURISA (masc.)',
    'pv_L20_018': 'කඩු සටන (instr. — කඩුවෙන්) — TAPPURISA (masc.)',
    'pv_L20_019': 'ලෝකයට ප්‍රයෝජනවත් (ඩැට්.) — TAPPURISA (masc.)',
    'pv_L20_020': 'සොරුන්ට ඇති බිය (abl. — සොරුන්ගෙන් ඇති බිය) — TAPPURISA (neut.)',
    'pv_L20_021': 'බුද්ධ ධර්මය (ජන.) — TAPPURISA (masc.)',
    'pv_L20_022': 'වනාන්තරයේ වාසය කිරීම (loc.) — TAPPURISA (masc.)',
    'pv_L20_023': 'ගෝලයා, ශිෂ්‍යයා (ගුරුවරයා අසල ජීවත් වන තැනැත්තා) — TAPPURISA (masc.)',
    'pv_L20_024': 'රජුට ඇති බිය (උපදේශනය) — TAPPURISA',
    'pv_L20_025': 'මව සහ පියා (mātā+pitaro, සමහර විට තප්පුරිස හෝ ද්වන්ද බහු වචන ආකාරයෙන්)',
    'pv_L20_026': 'සඳ සහ හිරු — DVANDA (masc. pl.)',
    'pv_L20_027': 'නම-සහ-ආකෘතිය (එකතු කිරීම) — DVANDA (neut.)',
    'pv_L20_028': 'සතුට සහ වේදනාව — DVANDA (neut.)',
    'pv_L20_029': 'අලි, ගවයින් සහ අශ්වයන් (පශු සම්පත් එකතුව) — DVANDA (neut.)',
    'pv_L20_030': 'පුතුන් සහ දියණියන් — DVANDA (masc. pl.)',
    'pv_L20_031': 'කාන්තා සහ පිරිමි — DVANDA (masc. pl.)',
    'pv_L20_032': 'ඇඳන් සහ ආසන (බහුවචන, සාමූහික) — DVANDA (neut. pl.)',
    'pv_L20_033': 'පිරිමි සහ කාන්තා සේවිකාවන් විසින් — DVANDA (fem./masc. pl. instr.)',
    'pv_L20_034': 'භික්ෂූන් සහ භික්ෂුණීන් — DVANDA',
    'pv_L20_035': 'කහ සිවුර → භික්ෂුව — BAHUBBĪHI (masc.)',
    'pv_L20_036': 'ධර්මය දුටු තැනැත්තා → උත්තමයා — BAHUBBĪHI (masc.)',
    'pv_L20_037': 'තෘෂ්ණාව අත්හැරිය තැනැත්තා → රහතන් වහන්සේ — BAHUBBĪHI (masc.)',
    'pv_L20_038': 'කෙලෙස් අවසන් කළ තැනැත්තා → රහතන් වහන්සේ — BAHUBBĪHI (masc.)',
    'pv_L20_039': 'විශ්වාසවන්ත හදවත් ඇති අය (විශ්වාසය ඇති) — BAHUBBĪHI (pl.)',
    'pv_L20_040': 'ක්‍රමානුකූලව, පියවරෙන් පියවර — AVYAYĪBHĀVA',
    'pv_L20_041': 'ගඟ අසල, ගඟ අසල — AVYAYĪBHĀVA',
    'pv_L20_042': 'පිටස්තර, නගරය ආසන්නයේ — AVYAYĪBHĀVA',
    'pv_L20_043': 'ශක්තිය අනුව — AVYAYĪBHĀVA',
    'pv_L20_044': 'පිළිවෙලින්, අනුපිළිවෙල අනුව — AVYAYĪBHĀVA',
    'pv_L20_045': 'යමෙකුගේ මුළු ජීවිතයම, කෙනෙකු ජීවත් වන තාක් කල් — AVYAYĪBHĀVA',
    'pv_L20_046': 'ආහාර ගැනීමෙන් පසු, දහවල් — AVYAYĪBHĀVA',
    'pv_L20_047': 'හැකියාව අනුව — AVYAYĪBHĀVA',
    'pv_L20_048': 'ධර්ම දානය (ධර්ම දානය) — TAPPURISA/KAMMADHĀRAYA (neut.)',
    'pv_L20_049': 'සරණාගත ස්ථාන තුන (සරණාගත වීමට ස්ථාන තුනක්) — DIGU/KAMMADHĀRAYA (neut.)',
    'pv_L20_050': 'දෙවියන්ගේ සහ මිනිසුන්ගේ — DVANDA (masc. pl. gen.)',
    'pv_L20_051': 'වෛද්‍ය වෘත්තිය (වෛද්‍යවරයෙකුගේ කාර්යය) — TAPPURISA (neut.)',
    'pv_L20_052': 'ගම සහ නගරවල — DVANDA (masc. pl. loc.)',
    'pv_L20_053': 'නපුරු ක්‍රියාව, නරක කම්ම (pāpa+කර්ම) — KAMMADHĀRAYA (neut.)',
    'pv_L20_054': 'සීතල ජලය (sīta+udaka) — KAMMADHĀRAYA (neut.)',
    'pv_L20_055': 'උණු වතුර (uṇha+udaka) — KAMMADHĀRAYA (neut.)',
    'pv_L20_056': 'ඇදහිල්ල ධනය ලෙස (ඇදහිල්ලේ ධනය) — KAMMADHĀRAYA (neut.)',
    'pv_L20_057': 'ප්‍රඥාවේ ධනය (ප්‍රඥාව ධනය ලෙස) — KAMMADHĀRAYA (neut.)',
    'pv_L20_058': 'ප්‍රේමණීය කරුණාවේ මනසකින් (දයානුකම්පිත මනස) — TAPPURISA/KAMMADHĀRAYA (instr.)',
    'pv_L20_059': 'විශාල මාලිගාව, උස් වේදිකාව (mahā+pāsāda) — KAMMADHĀRAYA (masc.)',
    'pv_L20_060': 'තපස්වරයාගේ ශුද්ධ ජීවිතය (තපස්වරයාගේ ධර්මය) — TAPPURISA (neut.)',
    'pv_L20_061': 'පිරිමි සහ ගැහැණු ගිහි අනුගාමිකයින් — DVANDA (pl. gen.)',
    'pv_L20_062': 'ළිං ජලය (kūpa+udaka) — TAPPURISA (neut.)',
    'pv_L20_063': 'මුහුදු ජලය (සමුද්ද+උදක) — TAPPURISA (neut.)',
    'pv_L20_064': 'පාද හතරේ සතුන් (catu+padāna) — DIGU/TAPPURISA (neut. pl.)',
    'pv_L20_065': 'ප්‍රතිපත්ති අට (සිල් පද අට) — DIGU (neut.)',
    'pv_L20_066': 'මරණයට ඇති බිය (maccu+bhaya) — TAPPURISA (neut.)',
    'pv_L20_067': 'සියල්ල දන්නා බුදුන් (sabbaññu+Buddha — appositional / KAMMADHĀRAYA)',
