    'pv_L03_006': 'මාමාගේ වත්ත ලස්සනයි.',
    'pv_L03_007': 'මට උපදෙස් ලැබේ.',
    'pv_L03_008': 'අපි කන්දෙන් බසිමු.',
    'pv_L03_009': 'මට ත්‍යාගය ලැබේ.',
    'pv_L03_010': 'කන්දෙන් ගස් වැටේ.',
    'pv_L03_011': 'ශිෂ්‍යයන් ගුරුවරුන් සමඟ පාඩම් කරයි.',
    'pv_L03_012': 'මම වැවට බසිමි.',
    'pv_L03_013': 'ඔහුට විපාකය ලැබේ.',
    'pv_L03_015': 'ශිෂ්‍යයින් පාඩම් කරයි.',
    'pv_L03_016': 'ඔහු අඹ ගෙඩියක් මිල දී ගනී.',
    'pv_L03_017': 'ඔහු අඹ ගෙඩියක් විකුණයි.',
    'pv_L03_018': 'ඔහු නිවසින් පිටතට යයි.',
    'pv_L03_019': 'ගසෙන් ගෙඩි වැටේ.',
    'pv_L03_021': 'ඔහු අශ්වයා පිට නගියි.',
    'pv_L03_022': 'ඔහු කන්දෙන් බැස එයි.',
    'pv_L03_023': 'ඔහු ධර්මය අසයි.',
    'pv_L04_001': 'මට අහසේ ඉර පේනවා.',
    'pv_L04_002': 'ඔහු ඇඳ මත නිදා ගනී.',
    'pv_L04_003': 'මම අහසේ සඳ දකිමි.',
    'pv_L04_004': 'කුරුල්ලන් ජීවත් වන්නේ ගස්වලය.',
    'pv_L04_005': 'ගොවියා ඇඳ මත නිදා ගනී.',
    'pv_L04_006': 'මසුන් උපදින්නේ මුහුදේය.',
    'pv_L04_007': 'මාළු වැවේ සෙල්ලම් කරයි.',
    'pv_L04_008': 'හිරු අහසේ බබළයි.',
    'pv_L04_009': 'අපි පාරේ සෙල්ලම් කරන්නේ නැහැ.',
    'pv_L04_010': 'වෙළෙන්දා වෙළදපොලේ ජීවත් වේ.',
    'pv_L04_011': 'සංචාරකයන් මාර්ගවල සැරිසරයි.',
    'pv_L04_012': 'ලෝකයේ බුදුවරු පහළ වෙති.',
    'pv_L04_013': 'ළමයි පාරේ සෙල්ලම් කරනවා.',
    'pv_L04_014': 'බුදුරජාණන් වහන්සේ ලොව පහළ වේ.',
    'pv_L04_015': 'ඔහු සඳ දකියි.',
    'pv_L04_016': 'භික්ෂුව වැඩ සිටින්නේ ආශ්‍රමයේය.',
    'pv_L04_017': 'ඔහු ඇඳ මත නිදා ගනී.',
    'pv_L04_018': 'තාපසයා ගම්වල සැරිසරයි.',
    'pv_L04_019': 'අද ඔහු එයි.',
    'pv_L04_020': 'ඔව්, මම යනවා.',
    'pv_L04_021': 'එයාත් යනවා.',
    'pv_L04_022': 'ඔහු යනවා.',
    'pv_L04_023': 'දැන් මම ධර්මය දේශනා කරමි.',
    'pv_L04_024': 'අපි මෙහි ජීවත් වෙමු.',
    'pv_L04_025': 'ඔබ (බහුවචන) එන්නේ කවදාද?',
    'pv_L04_026': 'ඔබ යන්නේ ඇයි?',
    'pv_L04_027': 'ඔහු ජීවත් වන්නේ කොහේද?',
    'pv_L04_028': 'ඔබ පැමිණෙන්නේ කොහෙන්ද?',
    'pv_L04_029': 'ඔහු යන්නේ නැත.',
    'pv_L04_030': 'ඔහු නැවත පැමිණේ.',
    'pv_L04_031': 'ඔහු දිනපතා ධර්මය අසයි.',
    'pv_L04_032': 'ඔහු නිතරම සිහියෙන් යුක්තව වාසය කරයි.',
    'pv_L04_033': 'අම්මා පුතා එක්ක යනවා.',
    'pv_L07_001': 'මම දහවල් බුදුන්ට ආචාර කළෙමි.',
    'pv_L07_002': 'මම අද උදේ ආහාරය ගත්තේ නැහැ.',
    'pv_L07_003': 'උදේ මට අවවාදය ඇහුණා.',
    'pv_L07_004': 'මම අද රාත්‍රී ආහාරය ගන්නවා.',
    'pv_L07_005': 'ඔහු බොහෝ වේලාවකින් පැමිණ නැත.',
    'pv_L07_006': 'ඔහුම යයි.',
    'pv_L07_007': 'ඔහු ඊයේ පැමිණියේය.',
    'pv_L07_008': 'ඔහු උදේ පාන්දරම ආවා.',
    'pv_L07_009': 'ඔහු ඉදිරියෙන් වාඩි විය.',
    'pv_L07_010': 'ඔහු බුදුන් වහන්සේ මෙන් ධර්මය දේශනා කරයි.',
    'pv_L07_011': 'මගේ තාත්තා යනවා.',
    'pv_L07_012': 'මගේ අම්මා එයි.',
    'pv_L07_013': 'අපේ නිවස මෙහි ඇත.',
    'pv_L07_014': 'ඔබේ පුතා යනවා.',
    'pv_L07_015': 'ඔබේ නම කුමක්ද?',
    'pv_L07_016': 'ඔබේ ගුරුවරයා ධර්මය දේශනා කරයි.',
    'pv_L07_017': 'ඔහුගේ පියා පැමිණියේය.',
    'pv_L07_018': 'ඇයගේ මව නිවසේ වාසය කරයි.',
    'pv_L07_019': 'ඔවුන්ගේ පුතුන් යනවා.',
    'pv_L07_020': 'ඔවුන්ගේ මව්වරුන් නිවසේ වාසය කරයි.',
    'pv_L08_001': 'වෙල් හිමියා ගෘහපතියන් හට ධර්මය දේශනා කළේය.',
    'pv_L08_002': 'ගින්න අබියස සිට මම බුදුන්ට ආචාර කළෙමි.',
    'pv_L08_003': 'අසිපත අතට ගත් රජු අශ්වයා පිට නැංගේය.',
    'pv_L08_004': 'අමුත්තන් අපේ ගෙදර ආවා.',
    'pv_L08_005': 'ගෘහපතියන් තුළ බුදුන් කෙරෙහි ශ්‍රද්ධාව ඇති විය.',
    'pv_L08_006': 'වඳුරන් ගසට නැඟ පලතුරු අනුභව කළහ.',
    'pv_L08_007': 'කවියා පොත සම්පාදනය කර රජුට දුන්නේය.',
    'pv_L08_008': 'රජතුමා මාණික්‍යය ලබාගෙන කවියාට දුන්නේය.',
    'pv_L08_009': 'අසිපත අතට ගත් රජු අශ්වයා පිට නැංගේය.',
    'pv_L08_010': 'අපේ නෑදෑයෝ ආගන්තුක ගෙදර දීර්ඝ කාලයක් ජීවත් වුණා.',
    'pv_L08_011': 'ඔබ ඔබේ ස්වාමිපුරුෂයාට ගෞරවයෙන් සලකන්න.',
    'pv_L08_012': 'කුරුල්ලන් කෙත්වල මෙනේරි දැක එය අනුභව කළහ.',
    'pv_L08_013': 'බත් පිසීමෙන් පසු ඔහු අනුභව කරයි.',
    'pv_L08_014': 'වැඩේ කරලා එයා යනවා.',
    'pv_L08_015': 'ධර්මය ඇසීමෙන් පසු ඔහුගේ සිත සන්සුන් වෙයි.',
    'pv_L08_016': 'ඔහු ගසට නැග ගෙඩි අනුභව කරයි.',
    'pv_L08_017': 'ඔහු කඩුව රැගෙන ගොඩ විය.',
    'pv_L08_018': 'බුදුන් වහන්සේ දැක උන්වහන්සේට ආචාර කරයි.',
    'pv_L08_019': 'බත් කෑ පසු ඔහු යයි.',
    'pv_L08_020': 'බුදුරජාණන් වහන්සේට ආචාර කිරීමෙන් පසු ඔහු වැඩ හිඳියි.',
    'pv_L11_001': 'ඔහු භික්ෂූන්ට ධර්මය දේශනා කරයි.',
    'pv_L11_002': 'භාග්‍යවතුන් වහන්සේ ධර්මය දේශනා කරන සේක.',
    'pv_L11_003': 'සියලු ප්‍රබුද්ධයා ප්‍රඥාවන්තයන් අතර උසස්ය.',
    'pv_L11_004': 'ගුරුවරයා ධර්මය දේශනා කරයි.',
    'pv_L11_005': 'මගේ තාත්තා බුදුන් වගේ.',
    'pv_L11_006': 'මගේ අයියා බුදුන් වගේ.',
    'pv_L11_007': 'ශිෂ්‍යයින්ට සැමවිටම කෘතඥ වීමට ඉඩ දෙන්න.',
    'pv_L11_008': 'ගොන් අලියා උණ බම්බු කොටුව කඩා දමයි.',
    'pv_L11_009': 'මම මරණයේ ධාරකය විනාශ කරමි.',
    'pv_L11_010': 'අපි භික්ෂුවගෙන් ප්‍රශ්නයක් අසමු.',
    'pv_L11_011': 'මම මී පැණි සමඟ කැඳ බොනවා.',
    'pv_L11_012': 'මම මී පැණි බොනවා.',
    'pv_L11_013': 'අපි එළකිරි බොමු.',
    'pv_L11_014': 'මනමාලියන් ඔවුන්ගේ ස්වාමිපුරුෂයන් සමඟ එකට ජීවත් වේ.',
    'pv_L11_015': 'මගේ අම්මා කන්‍යා සොහොයුරියක් වගේ.',
    'pv_L11_016': 'මම මරණයේ ධාරකය විනාශ කරමි.',
    'pv_L11_017': 'ආයුෂ ලැබීම නිසා මම බොහෝ කල් ජීවත් වෙමි.',
    'pv_L11_018': 'මගේ ඇස්වලින් මම නපුර දකින්නේ නැහැ.',
    'pv_L11_019': 'වනාන්තරයෙන් දර ගෙනැවිත් මම ගින්නක් ඇති කරමි.',
    'pv_L11_020': 'අපි එළකිරි බොමු.',
    'pv_L11_021': 'මම එළදෙනුන්ට තණකොළ දෙමි.',
    'pv_L11_022': 'මම පහනක් දල්වනවා.',
    'pv_L11_023': 'හාමුදුරුවන්ට ප්‍රශ්නය හොඳින් අවබෝධ වේවා.',
    'pv_L11_024': 'මරණයේ ධාරකය විනාශ කරන්න.',
    'pv_L11_025': 'හාමුදුරුවන්ට තරහා වෙන්න එපා.',
    'pv_L11_026': 'ආයුෂ ලැබුව ඔබට දීර්ඝායුෂ ලැබේවා!',
    'pv_L11_027': 'ස්වාමීනි, අපි භික්ෂුවගෙන් ප්‍රශ්නයක් අසමු.',
    'pv_L11_028': 'ආදරණීය මිත්‍රයා, කරුණාකර මෙහි එන්න.',
    'pv_L11_029': 'ස්වාමීනි, කරුණාකර ධර්මය දේශනා කරන්න.',
    'pv_L11_030': 'කරුණාකර හොඳින් සවන් දෙන්න.',
    'pv_L11_031': 'මම යන තුරු ඔබ මෙහි සිටින්න.',
    'pv_L11_032': 'මම යන තුරු ඔබ මෙහි සිටින්න.',
    'pv_L11_033': 'යන්න එපා!',
    'pv_L13_001': 'අපි උතුරේ ජීවත් වෙමු.',
    'pv_L13_002': 'ඔහුගේ නම කුමක්ද?',
    'pv_L14_001': 'බත් උයන මිනිසා.',
    'pv_L14_002': 'මම ඒ මිනිසා පාරේ යද්දී දැක්කා.',
    'pv_L14_003': 'ඔහු කතා කරමින් ඇවිදියි.',
    'pv_L14_004': 'දකින මිනිසා සඳ දකියි.',
    'pv_L14_005': 'කන බව පෙනෙන මිනිසා පලතුරු අනුභව කරයි.',
    'pv_L14_006': 'ඔහු වැඩ කරන අතරතුර ඇවිදියි.',
    'pv_L14_007': 'සියලු ස්ත්‍රීන් බණ අසමින් හිඳගත්හ.',
    'pv_L14_010': 'ඔහු එම ගස මත වාඩි වී සිටින කුරුල්ලා දකියි.',
    'pv_L14_011': 'මිනිසා බත් පිසිනු දකිනවා.',
    'pv_L14_012': 'ආරක්ෂා කෙරෙන නගරය ශක්තිමත් වේ.',
    'pv_L14_013': 'ඇසෙන ධර්මය ප්‍රවාහ ඵලයෙන් යුක්තය.',
    'pv_L14_014': 'කරගෙන යන වැඩේ හොඳ වේවා.',
    'pv_L14_015': 'ධර්මය දේශනා කරන විට ශ්‍රාවකයෝ නිශ්ශබ්ද වෙති.',
    'pv_L14_018': 'බොන වතුර සීතලයි.',
    'pv_L14_019': 'භික්ෂූහු දන්නා ධර්මය දේශනා කරති.',
    'pv_L14_020': 'මෙසේ මා අසා ඇත.',
    'pv_L14_021': 'සේවකයා පිසූ බත් මත ජීවත් වේ.',
    'pv_L14_022': 'මෙම නගරය ශක්තිමත් තැනැත්තා විසින් ආරක්ෂා කරන ලදී.',
    'pv_L14_023': 'ඔහු ගොස් ඇත.',
    'pv_L14_024': 'සිටගෙන සිටින මිනිසා පාරේ සිටගෙන සිටියි.',
    'pv_L14_025': 'අත්ත කැපුවේ ඔහු විසිනි.',
    'pv_L14_026': 'කැඩුණු මුට්ටිය බිමට වැටේ.',
    'pv_L14_027': 'ධර්මය දුටු තැනැත්තා රහතන් වහන්සේ නමකි.',
    'pv_L14_028': 'කෑම අනුභව කළ කෙනෙකුට තවත් කිසිවක් අවශ්‍ය නැත.',
    'pv_L14_029': 'ඔහු විසින් කළේ කුමක්ද?',
    'pv_L14_030': 'බොන ලද ජලය නැවත පානය නොකළ යුතුය.',
    'pv_L14_031': 'ධර්මය දේශනා කරන ලද්දේ බුදුන් වහන්සේ විසිනි.',
    'pv_L14_032': 'ඔහු ගෙදර ඇවිත්.',
    'pv_L14_033': 'දානය දිය යුත්තේ සත්පුරුෂයන් විසිනි.',
    'pv_L14_034': 'සත්‍ය ධර්මය දත යුතුය.',
    'pv_L14_035': 'බත් පිස ගත යුතුය.',
    'pv_L14_036': 'කුසලය කළ යුතුයි, අකුසලය නොකළ යුතුයි.',
    'pv_L14_037': 'ඔබ යා යුතුයි.',
    'pv_L14_038': 'භික්ෂූන් විසින් ධර්මය ශ්‍රවණය කළ යුතුය.',
    'pv_L14_039': 'ධර්මය ලොවට දේශනා කළ යුත්තේ භික්ෂූන් වහන්සේලා විසිනි.',
    'pv_L14_040': 'පියා ආචාර කිරීමට සුදුසුයි.',
    'pv_L14_041': 'මනස ආරක්ෂා කළ යුතුය.',
    'pv_L14_042': 'කළ යුතු කාර්යය මම කරමි.',
    'pv_L14_043': 'බුදුන් වහන්සේ දැකීමට සුදුසුය.',
    'pv_L14_044': 'රහතන් වහන්සේ වන්දනාවට සුදුසුයි.',
    'pv_L14_047': 'මා විසින් දෙන ලද දානය.',
    'pv_L14_055': 'භාග්‍යවතුන් වහන්සේ වැඩ සිටිනවා.',
    'pv_L14_056': 'ඔවුන්ගෙන් කිසිවකුට හානියක් නොකරයි.',
    'pv_L14_057': 'සියලු සත්වයෝ සුඛිත මුදිත වෙත්වා.',
    'pv_L14_058': 'ඔහු මා වෙත ළඟා විය.',
    'pv_L14_059': 'රයිනෝසිරස් අං මෙන් ඔහුට තනිව ජීවත් වීමට ඉඩ දෙන්න.',
    'pv_L14_060': 'සියලු සත්වයන් දෙසට සැරයටිය තැබීමෙන්.',
    'pv_L14_061': 'ඇලීම නිසා දුක උපදී.',
    'pv_L14_062': 'සහකාරියක් නොමැතිව සතුටක් නැත.',
    'pv_L14_063': 'තෘෂ්ණාවෙන් නිදහස් වූ කෙනෙකුට දුකක් නැත.',
    'pv_L14_064': 'ඔහු ශුද්ධ ජීවිතය පුරුදු කරයි.',
    'pv_L15_001': 'මේ මිනිසා යනවා.',
    'pv_L15_002': 'මට මේ මිනිහව පේනවා.',
    'pv_L15_006': 'ඔහු මෙම නිවසේ වාසය කරයි.',
    'pv_L15_007': 'මේ මිනිස්සු යනවා.',
    'pv_L15_009': 'ඔවුන් ජීවත් වන්නේ මෙම ගම්වලයි.',
    'pv_L15_010': 'මෙය පලතුරකි.',
    'pv_L15_011': 'මේ අය කාන්තාවන්.',
    'pv_L15_012': 'දානය දුන්නේ මෙම කාන්තාව විසිනි.',
    'pv_L15_015': 'ඒ මිනිසා.',
    'pv_L15_030': 'මෙය මගේ අවසන් උපතයි.',
    'pv_L15_031': 'ඔහු උස් අසුනක වාඩි විය.',
    'pv_L15_032': 'රහතන් වහන්සේ, පරිපූර්ණ බුද්ධත්වයට පත් තැනැත්තා.',
    'pv_L15_033': 'භාග්‍යවතුන් වහන්සේට, රහතන් වහන්සේට, සර්වඥයන් වහන්සේට උපහාරය.',
    'pv_L15_034': 'ඔවුන් යන්නේ දිගු මාර්ගයෙනි.',
    'pv_L15_035': 'වර්ණ කළු.',
    'pv_L15_036': 'මේවා කුඩා පලතුරු වේ.',
    'pv_L15_037': 'මැද මාර්ගය.',
    'pv_L15_038': 'මට විශාල නිවසක් පෙනේ.',
    'pv_L15_039': 'බුද්ධ වන්දනාව.',
    'pv_L15_040': 'ඔහු පහත් අසුනක වාඩි විය.',
    'pv_L15_041': 'වර්ණය නිල්.',
    'pv_L15_042': 'මැද මාර්ගය.',
    'pv_L15_043': 'කහ මල්.',
    'pv_L15_044': 'රතු මල්.',
    'pv_L15_045': 'සුදු අශ්වයා.',
    'pv_L15_046': 'සීතල ජලය පානය නොකළ යුතුය.',
    'pv_L15_047': 'සියලු සත්වයෝ සුඛිත මුදිත වෙත්වා.',
    'pv_L15_048': 'තරුණ වෛද්‍යවරයා.',
    'pv_L15_049': 'ඔහු උස් අසුනක වාඩි විය.',
    'pv_L15_050': 'ඔහු උණු වතුරෙන් මුහුණ සෝදා ගනී.',
    'pv_L15_051': 'එය ශක්තිමත් රජු විසින් ආරක්ෂා කරන ලදී.',
    'pv_L15_052': 'ධනවත් මිනිසා.',
    'pv_L15_053': 'හිම කන්ද (හිමාලය)',
    'pv_L15_054': 'නෑදෑයන් සිටින මිනිසා.',
    'pv_L15_056': 'ගුණවත් අය සතුටින් ජීවත් වෙති.',
    'pv_L15_060': 'බුදුවරු යනු ඇස් ඇති (පැහැදිලිව දකින) අයයි.',
    'pv_L15_063': 'යමෙකුට සත්පුරුෂයන් ඇසුරු කිරීමට ඉඩ දෙන්න.',
    'pv_L15_065': 'ගුණවත් අය ඇසුරට සුදුසුයි.',
    'pv_L15_066': 'ධෛර්ය සම්පන්න අය බියෙන් පලා නොයති.',
    'pv_L17_001': 'මක්නිසාද යමෙකු සැබවින්ම තමාගේම රැකවරණයකි.',
    'pv_L17_002': 'රජු මාලිගාවේ වාසය කරයි.',
    'pv_L17_003': 'ඇමතිවරුන්ට රජවරුන්ගෙන් ධනය ලැබේ.',
    'pv_L17_004': 'මෙය මගේම ප්‍රයෝජනයකි.',
    'pv_L17_005': 'මක්නිසාද යමෙකු සැබවින්ම තමාගේම රැකවරණයකි.',
    'pv_L17_006': 'රජු මාලිගාවේ වාසය කරයි.',
    'pv_L17_007': 'අපේ රටේ හිටියා ගුණවත් රජෙක්.',
    'pv_L17_008': 'යමෙක් තමා විසින්ම අපවිත්‍ර වේ.',
    'pv_L17_009': 'එසේ සිතීම, මෝඩයා දුක් වේ.',
    'pv_L17_010': 'යමෙක් තමා විසින්ම පවිත්‍ර වේ.',
    'pv_L17_011': 'මක්නිසාද යමෙක් සැබවින්ම තමාගේම රැකවරණයකි.',
    'pv_L17_012': 'ඔහු, "එය කරන්න"',
    'pv_L17_013': 'සරණාගතයෙකු විය හැක්කේ වෙන කවුරුන්ද?',
    'pv_L18_001': 'ගුරුවරයා ධර්මය දේශනා කරයි.',
    'pv_L18_003': 'මම ගුරුවරයා දකිමි.',
    'pv_L18_004': 'ධර්මය ශාස්තෘන් වහන්සේ විසින් දේශනා කරන ලදී.',
    'pv_L18_005': 'ගුරුවරයාගේ ගෝලයා.',
    'pv_L18_006': 'ගුරුවරයා වෙත රැස් වූ පසු.',
    'pv_L18_007': 'පියා තම පුතා දකියි.',
    'pv_L18_008': 'මව තම දරුවා පෝෂණය කරයි.',
    'pv_L18_009': 'අයියා අයියාව දකිනවා.',
    'pv_L18_010': 'දුව ඇගේ මව දකී.',
    'pv_L18_011': 'සැමියා තම බිරිඳට ධනය ලබා දෙයි.',
    'pv_L18_012': 'දෙන්නා දානය දෙයි.',
    'pv_L18_013': 'ජයග්‍රාහකයා Māra ජය ගනී.',
    'pv_L18_014': 'කරන්නා ක්‍රියාව සිදු කරයි.',
    'pv_L18_015': 'මුණුපුරා ඔහුගේ ආච්චිව දකී.',
    'pv_L18_016': 'ඥාතියා ඥාතියෙකු දකියි.',
    'pv_L18_017': 'මාර්ගෝපදේශය මාර්ගය පෙන්වයි.',
    'pv_L18_018': 'ශ්‍රාවකයා ධර්මය ශ්‍රවණය කරයි.',
    'pv_L18_019': 'පැහැදිලි කරන්නා ධර්මය පැහැදිලි කරයි.',
    'pv_L18_020': 'ඔහු සේවකයාට බත් උයනවා.',
    'pv_L18_022': 'ඔහු මිනිසාව උයනවා.',
    'pv_L18_024': 'ඔහු මිනිසාට දානයක් දීමට සලස්වයි.',
    'pv_L18_026': 'ඔහු මිනිසාට ගස කැපීමට සලස්වයි.',
    'pv_L18_028': 'ඔහු මිනිසා (යමෙකු) ගමට ගෙන යාමට සලස්වයි.',
    'pv_L18_029': 'ඔහු මිනිසා නිවසින් පිටවීමට සලස්වයි.',
    'pv_L18_030': 'භික්ෂුව ධර්මය ප්‍රකාශ කරයි.',
    'pv_L18_031': 'භික්ෂුව සන්සුන් බව සහ තීක්ෂ්ණ බුද්ධිය වඩයි.',
    'pv_L18_032': 'ගුරුවරයාට පාරායනය කරන්නා විසින් පද කියන්නට ඇත.',
    'pv_L18_033': 'ඔහු සේවකයා වැඩ කරවයි.',
    'pv_L18_034': 'රජු මිනිසුන්ව වැඩ කරවයි.',
    'pv_L18_035': 'ගුරුවරයා ශ්‍රාවකයන්ට ධර්මය දේශනා කිරීමට සලස්වයි.',
    'pv_L18_036': 'අම්මා දරුවා නාවයි.',
    'pv_L18_037': 'ගුරුවරයා විසින් භික්ෂූන් වහන්සේලා ආරාමයෙහි වැඩ වසන සේක.',
    'pv_L18_038': 'ගුරුවරයා ජීවීන් අවදි කරයි.',
    'pv_L18_039': 'ගුරුවරයා සිසුන්ට මන්ත්‍ර ඉගෙන ගැනීමට සලස්වයි.',
    'pv_L18_040': 'ගුරුවරයා භික්ෂූන්ට උපදෙස් දෙයි.',
    'pv_L18_041': 'ශ්‍රාවකයා ධර්මය ශ්‍රවණය කරයි.',
    'pv_L18_042': 'රජුගේ රාජධානිය විශාලය.',
    'pv_L18_043': 'ආගන්තුකයාට ආහාර වේලක් ලබා දිය යුතුය.',
    'pv_L18_044': 'මිණිබිරිය ඇගේ ආච්චිව දකියි.',
    'pv_L18_045': 'ඇය ලිපියක් ලියනවා.',
    'pv_L18_046': 'වනාන්තරයේ ගිනි ඇවිළෙයි.',
    'pv_L18_047': 'දර ගිනි දල්වයි.',
    'pv_L18_048': 'ඔහු දානයක් දෙනවා.',
    'pv_L18_049': 'ඔවුන් දේශන ශාලාවේ ධර්මය දේශනා කරති.',
    'pv_L18_050': 'පියා තම පුතාට ආදරය කරයි.',
    'pv_L18_051': 'අම්මා දුවට රත්තරන් දෙනවා.',
    'pv_L18_052': 'බිරිඳ තම සැමියා දකියි.',
    'pv_L18_053': 'දරුවා තම මව දකී.',
    'pv_L18_054': 'රජු රට පාලනය කරයි.',
    'pv_L18_055': 'ගුරුවරයා විසින් ගෝලයා විසින් පාඩම කීමට සලස්වයි.',
    'pv_L18_056': 'ශිෂ්‍යයා ගුරුවරයා වෙත ළඟා වේ.',
    'pv_L18_057': 'භික්ෂුව (මනස) වඩයි.',
    'pv_L18_058': 'ඔහු නිවසින් පිටතට යයි.',
    'pv_L18_059': 'භික්ෂූන් වහන්සේ ආරාමයේ වැඩ වසති.',
    'pv_L18_060': 'ධර්මය දේශනා කරනු ලැබේ.',
    'pv_L19_001': 'එළදෙනුන් පිට්ටනියට ගියා.',
    'pv_L19_002': 'සිතෙන් සංයමයෙන් සිටීම හොඳය.',
    'pv_L21_a': 'කන්ද තරම් ඈත — ආපසු යාමට — ගෙන ඒමට',
    'pv_L21_abhi': 'උසස් ධර්මය — උසස් දැනුම — හොඳින් අවබෝධ කර ගැනීමට',
    'pv_L21_adhi': 'උසස් තත්වයේ වාසය කිරීමට — ඇතුළු වීමට, ලබා ගැනීමට —',
    'pv_L21_anu': 'අනුගමනය කිරීමට — නියෝජ්‍ය රජු — අනුව',
    'pv_L21_apa': 'දේශන ශාලාවෙන් පිටව යාමට — අවවාද කිරීමට —',
    'pv_L21_api': 'වසා ගැනීමට, පියනක්, විසි කිරීමට, තොප්පියක්',
    'pv_L21_ati': 'ඉතා ලස්සනයි — ඔබ්බට යාමට, උල්ලංඝනය කිරීමට — තරණය කිරීමට',
    'pv_L21_ava': 'පල්ලමට — ඉවත් කිරීමට — හෙළා දැකීමට',
    'pv_L21_du': 'නරක ගමනාන්තයක් — මෙල්ල කිරීමට අපහසු — තේරුම් ගැනීමට අපහසු',
    'pv_L21_ni': 'පිටතට යාමට — ආහාර නොමැතිව — අවසන් කිරීමට',
    'pv_L21_ni2': 'ඉවත් කිරීමට, ඇද ගැනීමට — සෞඛ්‍ය සම්පන්න — වියලි, රස රහිත',
    'pv_L21_pa': 'ඉතා ශක්තිමත් — ඇවිදීමට — පිටත් වීමට',
    'pv_L21_para': 'පහරට - පරාජයට - ශක්තිය යෙදවීමට, උත්සාහ කිරීමට',
    'pv_L21_pari': 'තබා ගැනීමට — වට කිරීමට — සම්පූර්ණයෙන්ම පිරිසිදු',
    'pv_L21_pati': 'ආපසු පියවරට — පිළිතුරු දීමට — ප්‍රතිලෝම දිශාවට',
    'pv_L21_sam': 'ස්වයං පිබිදීම — හමුවීමට, රැස් කිරීමට — රැස් කිරීමට, රැස් කිරීමට',
    'pv_L21_su': 'හොඳ ගමනාන්තයක් - සිල්වත් පුද්ගලයෙක් - දක්ෂ ලෙස දේශනා කිරීමට - කිරීමට පහසුය',
    'pv_L21_u': 'ඉහළට - ඉහළට - ඉහළට යාමට - ඉපදීමට, වැඩි වීමට',
    'pv_L21_upa': 'ළඟා වීමට — නියෝජ්‍ය රජු — ඇලී සිටීම, අල්ලා ගැනීම',
    'pv_L21_vi': 'පිරිසිදු — පැහැදිලිව දැකීමට — විමුක්තිය — ගමන් කිරීමට',
    'pv_L22_panna': 'ප්‍රඥාව + a = ප්‍රඥාව ඇති පුද්ගලයෙක්',
    'pv_L22_saddha': 'ඇදහිල්ල + a = ඇදහිල්ල ඇති පුද්ගලයෙක්',
    'pv_L22_dhammika': 'ධම්ම + ඉකා = කෙළින්',
    'pv_L22_nagarika': 'නගරය + ika = නගරයට අයත්',
    'pv_L22_venayika': 'විනය + ika = විනයෙහි දක්ෂ අයෙක්',
    'pv_L22_dandi': 'කාර්ය මණ්ඩලය + ī = කාර්ය මණ්ඩලයක් ඇති අයෙක්',
    'pv_L22_gunavantu': 'සුචරිතය + වන්තු = ගුණවත් පුද්ගලයෙකි',
    'pv_L22_medhavi': 'ප්‍රඥාව + vī = ප්‍රඥාවේ පුද්ගලයෙකි',
    'pv_L22_ayomaya': 'යකඩ + මායා = යකඩ වලින් සාදා ඇත',
    'pv_L22_darumaya': 'ලී + මායා = ලී වලින් සාදා ඇත',
    'pv_L22_manomaya': 'සිත + මායා = මනසින් සෑදී ඇත (a→o)',
    'pv_L22_janata': 'ජනතාව + tā = සමූහයක්',
    'pv_L22_dhammata': 'ධර්ම + tā = ස්වභාවය',
    'pv_L22_arogya': 'රෝගයෙන් නිදහස් වීම + යා = සෞඛ්‍යය',
    'pv_L22_balatta': 'මෝඩයා + tta = මෝඩකම',
    'pv_L22_seyya': 'හොඳ → වඩා හොඳ → හොඳම',
    'pv_L22_settha': 'හොඳ → වඩා හොඳ → හොඳම',
    'pv_L23_bhava': 'වීමට, හටගැනීමට → පැවැත්ම',
    'pv_L23_dosa': 'කෝපය → කෝපය, නරක කැමැත්ත',
    'pv_L23_moha': 'මුළාව → මෝහය, අවිද්‍යාව',
    'pv_L23_lobha': 'ආශා කිරීමට → තණ්හාව',
    'pv_L23_khaya': 'විනාශ වීමට → විනාශය',
    'pv_L23_gamana': 'යන්න → යනවා, චලනය',
    'pv_L23_karana': 'කරන්න → කරමින්',
    'pv_L23_karaka': 'කරන්න → කරන්නා, නියෝජිතයා',
    'pv_L23_dhammapiti': 'ධර්මය + බීමට → ධර්මය පානය කරන්නා',
    'pv_L23_gati': 'යන්න → ගමනාන්තය, රාජධානිය',
    'pv_L23_mutti': 'නිදහස් → විමුක්ති',
    'pv_L23_sati': 'මතක තබා ගැනීමට → සිහිය',
    'pv_L23_karaniya': 'කිරීමට → කිරීමට, එය කළ යුතු',
    'pv_L23_pujaniya': 'නමස්කාරය → නමස්කාරයට සුදුසුයි',
    'pv_L23_deyya': 'දෙන්න → දෙන්න',
    'pv_L23_papakari': 'නපුරු + කරන → නපුර කරන කෙනෙක්',
    'pv_L23_saccavadi': 'සත්‍යය + කථනය → සත්‍යය කතා කරන්නා',
    'pv_L23_kodhana': 'කෝපය → පහසුවෙන් කෝප වන අයෙක්',
    'pv_L23_gantukama': 'යන්න (inf.) + ආශාව → යන්න කැමති කෙනෙක්',
    'pv_L24_lokagga': 'පෙර ස්වරය ඉවත් කර ඇත.',
    'pv_L24_chayava': 'පහත ස්වරය ඉවත් කර ඇත.',
    'pv_L24_suriyodaya': 'පෙර ස්වරය ඉවත් කළ විට u වෙනුවට o යන්න ලැබේ.',
    'pv_L24_buddhanussati': 'පහත ස්වරය දිගු කර ඇත.',
    'pv_L24_vyākato': 'i වෙනත් ස්වරයකට පෙර y මගින් ප්‍රතිස්ථාපනය වේ.',
    'pv_L24_accantam': 'අති/ඉති/පටි හි ටී සීසී වෙයි.',
    'pv_L24_abbhuggato': 'අභි ස්වරයකට පෙර අබ්භ වෙයි.',
    'pv_L24_appamado': 'ස්වරයකට පසුව එන ව්‍යාංජනාක්ෂරය දෙගුණ වේ.',
    'pv_L24_esa': 'අවසාන o ව්‍යාංජනාක්ෂරයකට පෙර a වෙත වෙනස් වේ.',
    'pv_L24_saddhammo': 'අභිලාශය: පළමු ව්‍යාංජනාක්ෂරයට එහි අභිලාෂය නැති වේ.',
    'pv_L24_sambodhi': 'එකම කණ්ඩායමේ නාසයට වෙනස් වේ.',
    'pv_L24_sannipato': 'n කණ්ඩායමට පෙර n වෙත වෙනස් වේ.',
    'pv_L24_tanneva': 'ඊට පෙර ññ වෙත වෙනස් වේ.',
    'pv_L24_sannamo': 'ṃ→ññ y ට පෙර, y ඉවත් කර ඇත.',
    'pv_L25_puriso': 'මිනිසා යනවා.',
    'pv_L25_raja': 'ඔහු රජ වී ඇත.',
    'pv_L25_putta': 'පුතා, මෙහාට එන්න!',
    'pv_L25_lekhanam': 'මම ලිපියක් ලියනවා.',
    'pv_L25_gamam': 'ඔහු ගමට යනවා.',
    'pv_L25_sukham': 'රජු සතුටින් ජීවත් වේ.',
    'pv_L25_acariyena': 'පොත දුන්නේ ගුරුවරයා විසිනි.',
    'pv_L25_hatthena': 'ඔහු ඔහුගේ දෑතින් වැඩ කරයි.',
    'pv_L25_vijjaya': 'ප්‍රඥාවට පින්සිදු වෙන්න, ඔහු ජීවත් වෙනවා.',
    'pv_L25_satena': 'එය සියයකට මිල දී ගෙන ඇත.',
    'pv_L25_pitara': 'පියාට සමානයි.',
    'pv_L26_paccate': 'පිසීමට → පිසීමට (මූල සහ අවසානය අතර "ya" එකතු කරන්න)',
    'pv_L26_diyate': 'දෙන්න → දිය යුතු (ā → ī ya ට පෙර)',
    'pv_L26_rakkhiyate': 'ආරක්ෂා කිරීමට → ආරක්ෂා කිරීමට (a → ī)',
    'pv_L26_niyate': 'ඊයම් කිරීමට → නායකත්වයට',
