    'pv_L19_002': 'စိတ်ကို ချုပ်တည်းခြင်းသည် ကောင်း၏။',
    'pv_L21_a': 'တောင်ပေါ်—ပြန်ရန်—ယူဆောင်လာရန်',
    'pv_L21_abhi': 'သာလွန်သော တရား— မြင့်မြတ်သောပညာ — စေ့စေ့စပ်စပ် နားလည်ရန်',
    'pv_L21_adhi': 'နေထိုင်ရန် — ဝင်ရန်၊ ရရှိရန် — မြင့်မားသောအခြေအနေ',
    'pv_L21_anu': 'နောက်သို့—ဒုဘုရင်—',
    'pv_L21_apa': 'ထွက်သွားရန် — ဆုံးမရန် — ဟောပြောပွဲခန်းမ',
    'pv_L21_api': 'ပိတ်ရန်၊ အဖုံးတစ်ခု၊ ပစ်ရန်၊ ဦးထုပ်',
    'pv_L21_ati': 'လွန်စွာလှပသော — ကျော်သွားရန်၊ ချိုးဖောက်ရန် — ဖြတ်ကျော်ရန်',
    'pv_L21_ava': 'ရာထူးမှဆင်းရန် — ဖယ်ထုတ်ရန် — မထီမဲ့မြင်ပြုရန်',
    'pv_L21_du': 'မကောင်းတဲ့ ဦးတည်ရာ— ယဉ်ပါးရခက် — နားလည်ရခက်',
    'pv_L21_ni': 'ထမင်းမစားဘဲ အပြင်ထွက်ရန်—အဆုံးသတ်ရန်',
    'pv_L21_ni2': 'ဖယ်ထုတ်ရန်၊ ဆွဲထုတ်ရန် — ကျန်းမာ — ခြောက်သွေ့၊ အရသာမရှိသော',
    'pv_L21_pa': 'လမ်းလျှောက်ရန်—အလွန်သန်မာသော—အပြင်ထွက်ရန်',
    'pv_L21_para': 'ကျဆုံးခြင်း—ရှုံးနိမ့်ခြင်း—အားစိုက်ထုတ်ရန်၊ အားထုတ်ရန်',
    'pv_L21_pari': 'အပေါ်၌ နေရာချရန် — ဝန်းရံရန် — လုံးဝစင်ကြယ်သည်',
    'pv_L21_pati': 'နောက်ပြန်ဆုတ်ရန် — ဖြေရန် — ပြောင်းပြန်ဦးတည်ချက်',
    'pv_L21_sam': 'မိမိကိုယ်မိမိ နိုးကြားခြင်း — တွေ့ဆုံရန်၊ စုဝေးရန် — စုသိမ်းရန်၊ စုဆောင်းရန်',
    'pv_L21_su': 'ကောင်းသော ဦးတည်ရာ— သီလရှိသော ပုဂ္ဂိုလ် — ကျွမ်းကျင်စွာ တရားဟောရန် — လွယ်ကူသည်',
    'pv_L21_u': 'ထရန်—ထရန်—တက်ရန်—မွေးဖွားရန်၊ တိုးပွားရန်',
    'pv_L21_upa': '— လက်ထောက်မင်းကြီးထံ ချဉ်းကပ်ရန် — တွယ်ကပ်ခြင်း၊ ဆုပ်ကိုင်ခြင်း',
    'pv_L21_vi': 'ရှင်းရှင်းလင်းလင်းမြင်ရန်—လွတ်မြောက်မှု—ခရီးသွားခြင်း',
